create function pg_temp.export_completion() returns jsonb language sql as $$select jsonb_build_object('kind','validatedReviewExport','projectionArtifact',pg_temp.produced(pg_temp.val('export-context')->'data'->'producerContext'->>'projectionArtifactId','reportProjection','lca.study-report-view.v1','projection',repeat('e',64)),'resourcesArtifact',pg_temp.produced(pg_temp.val('export-context')->'data'->'producerContext'->>'resourcesArtifactId','renderResources','lca.study-export-manifest.v2','resources',private.study_reporting_digest(null,pg_temp.manifest()),octet_length(private.study_reporting_canonical(pg_temp.manifest()))),'bundleArtifact',pg_temp.produced(pg_temp.val('export-context')->'data'->'producerContext'->>'bundleArtifactId','reportExportBundle','lca.study-export-bundle.v2','bundle',repeat('f',64)),'manifest',pg_temp.manifest(),'receipt',jsonb_build_object('schemaVersion','lca.study-export-receipt.v2','manifestHash',private.study_reporting_digest('lca.study-export-signature.v1',pg_temp.manifest()),'keyId','study906-key','algorithm','Ed25519','signature',repeat('A',86)))$$;
