select is(pg_temp.cmd('member.set','{"target":{"type":"study","id":"90600000-0000-4000-8000-000000000010","expectedRevision":1},"memberId":"89400000-0000-4000-8000-000000000002","role":"editor"}','personal-editor')->>'code','CAPABILITY_UNAVAILABLE','personal editor authority is not widened');
